<?php
namespace Tests\Feature;
use App\Models\{Company,User,Customer,Service,Appointment,PatientFollowup as Followup,FollowupEvent as Event,AppointmentConfirmation};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\{Str,Carbon};
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class FollowupTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $owner;private User $dentist;private Customer $patient;private Service $service;
 protected function setUp():void {parent::setUp();$this->travelTo(Carbon::parse('2026-10-01 12:00:00','UTC'));$this->company=Company::create(['name'=>'Clínica teste','slug'=>'followups','booking_timezone'=>'America/Sao_Paulo']);$this->owner=$this->user('owner');$this->dentist=$this->user('professional');$this->patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Paciente teste','phone'=>'75999991234','active'=>true]);$this->service=Service::create(['company_id'=>$this->company->id,'name'=>'Consulta teste','duration_minutes'=>30,'price_cents'=>10000,'active'=>true]);$this->actingAs($this->owner);}
 private function user(string $role,?Company $company=null):User{return User::create(['company_id'=>($company??$this->company)->id,'name'=>'Usuário '.$role,'email'=>Str::uuid().'@example.test','password'=>'OnlyTest-2026','role'=>$role,'active'=>true]);}
 private function form(array $changes=[]):array{return array_replace(['request_id'=>(string)Str::uuid(),'customer_id'=>(string)$this->patient->id,'professional_id'=>(string)$this->dentist->id,'service_id'=>(string)$this->service->id,'kind'=>'recall','from_date'=>'2026-10-02','to_date'=>'2026-10-10','period'=>'morning','note'=>'Ligar após as 14h'],$changes);}
 private function entry(array $changes=[]):Followup{$this->post(route('followups.store'),$this->form($changes))->assertSessionHasNoErrors();return Followup::latest('id')->firstOrFail();}
 private function booking(Followup $f,array $changes=[]):array{return array_replace(['customer_id'=>(string)$this->patient->id,'professional_id'=>(string)$this->dentist->id,'service_id'=>(string)$this->service->id,'starts_at'=>'2026-10-02T10:00','ends_at'=>'2026-10-02T10:30','status'=>'scheduled','followup_id'=>(string)$f->id,'followup_revision'=>(string)$f->revision],$changes);}
 private function book(Followup $f):Appointment{$this->post(route('appointments.store'),$this->booking($f))->assertSessionHasNoErrors();return Appointment::latest('id')->firstOrFail();}
 public function test_create_retry_encryption_views_and_revision():void{$form=$this->form();$this->post(route('followups.store'),$form)->assertSessionHasNoErrors();$this->post(route('followups.store'),$form)->assertSessionHasNoErrors();$this->assertDatabaseCount('patient_followups',1);$f=Followup::sole();$this->assertStringNotContainsString('Ligar após',DB::table('patient_followups')->value('note'));$this->assertStringNotContainsString('Ligar após',DB::table('followup_events')->value('payload'));foreach(['index','create','show','edit'] as $page)$this->get(route('followups.'.$page,in_array($page,['show','edit'])?$f->id:[]))->assertOk()->assertHeader('Cache-Control','no-store, private');$form['revision']=$f->revision;$form['period']='afternoon';$this->put(route('followups.update',$f->id),$form)->assertSessionHasNoErrors();$this->put(route('followups.update',$f->id),$form)->assertSessionHasErrors('revision');$this->assertSame('afternoon',$f->fresh()->period);$this->assertSame('morning',Event::oldest('id')->first()->payload['period']);}
 public function test_manual_contact_retry_and_no_automatic_send():void{$f=$this->entry();$data=['revision'=>$f->revision,'request_id'=>(string)Str::uuid(),'channel'=>'phone','note'=>'Paciente pediu contato amanhã','acknowledge'=>'1'];$this->get(route('followups.show',$f->id))->assertSee('https://wa.me/5575999991234',false)->assertSee('Preparar mensagem no WhatsApp');$this->assertSame('pending',$f->fresh()->status);$this->post(route('followups.contact',$f->id),$data)->assertSessionHasNoErrors();$this->post(route('followups.contact',$f->id),$data)->assertSessionHasNoErrors();$this->assertSame(1,Event::where('event','contacted')->count());$this->assertSame('contacted',$f->fresh()->status);$this->assertNotNull($f->fresh()->last_contact_at);$data['request_id']=(string)Str::uuid();$this->post(route('followups.contact',$f->id),$data)->assertSessionHasErrors('revision');unset($data['acknowledge']);$this->post(route('followups.contact',$f->id),$data)->assertSessionHasErrors('acknowledge');}
 public function test_prefilled_booking_atomic_link_and_duplicate_prevention():void{$f=$this->entry();$this->get(route('appointments.create',['followup_id'=>$f->id]))->assertOk()->assertSee('name="followup_id"',false)->assertViewHas('appointment',fn($a)=>$a->customer_id===$f->customer_id);$a=$this->book($f);$this->assertSame('scheduled',$f->fresh()->status);$this->assertSame($a->id,$f->fresh()->appointment_id);$this->post(route('appointments.store'),$this->booking($f,['starts_at'=>'2026-10-02T11:00','ends_at'=>'2026-10-02T11:30']))->assertSessionHasErrors('followup_id');$this->assertDatabaseCount('appointments',1);$this->get(route('followups.show',$f->id))->assertOk()->assertSee('Abrir agendamento');}
 public function test_booking_rejects_stale_preferences_wrong_patient_period_dates_and_past():void{$f=$this->entry();$patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Outro paciente','active'=>true]);foreach([['followup_revision'=>'999'],['customer_id'=>(string)$patient->id],['starts_at'=>'2026-10-02T14:00','ends_at'=>'2026-10-02T14:30'],['starts_at'=>'2026-10-11T10:00','ends_at'=>'2026-10-11T10:30'],['starts_at'=>'2026-09-30T10:00','ends_at'=>'2026-09-30T10:30'],['status'=>'completed']] as $bad)$this->post(route('appointments.store'),$this->booking($f,$bad))->assertSessionHasErrors('followup_id');$this->assertDatabaseCount('appointments',0);$this->assertSame('pending',$f->fresh()->status);}
 public function test_existing_slot_conflict_does_not_consume_followup():void{$f=$this->entry();$a=$this->booking($f);unset($a['followup_id'],$a['followup_revision']);$this->post(route('appointments.store'),$a)->assertSessionHasNoErrors();$this->post(route('appointments.store'),$this->booking($f))->assertSessionHasErrors('starts_at');$this->assertSame('pending',$f->fresh()->status);$this->assertDatabaseCount('appointments',1);}
 public function test_cancel_reopens_and_rescheduling_or_completion_retains_link():void{$f=$this->entry();$a=$this->book($f);$data=$this->booking($f,['starts_at'=>'2026-10-03T11:00','ends_at'=>'2026-10-03T11:30']);unset($data['followup_id'],$data['followup_revision']);$this->put(route('appointments.update',$a->id),$data)->assertSessionHasNoErrors();$this->assertSame('scheduled',$f->fresh()->status);$data['status']='completed';$this->put(route('appointments.update',$a->id),$data)->assertSessionHasNoErrors();$this->assertSame('scheduled',$f->fresh()->status);$data['status']='cancelled';$this->put(route('appointments.update',$a->id),$data)->assertSessionHasNoErrors();$this->assertSame('pending',$f->fresh()->status);$this->assertNull($f->fresh()->appointment_id);$this->assertSame(1,Event::where('event','reopened')->count());}
 public function test_delete_and_patient_change_reopen_only_linked_request():void{$f=$this->entry();$a=$this->book($f);$patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Outro paciente','active'=>true]);$data=$this->booking($f,['customer_id'=>(string)$patient->id]);unset($data['followup_id'],$data['followup_revision']);$this->put(route('appointments.update',$a->id),$data)->assertSessionHasNoErrors();$this->assertSame('pending',$f->fresh()->status);$this->delete(route('appointments.destroy',$a->id))->assertRedirect();$a=$this->book($f->fresh());$this->delete(route('appointments.destroy',$a->id))->assertRedirect();$this->assertSame('pending',$f->fresh()->status);$this->assertSame(2,Event::where('event','reopened')->count());}
 public function test_public_patient_cancellation_reopens_once():void{$f=$this->entry();$a=$this->book($f);$this->post(route('reminders.issue',$a->id),['request_id'=>(string)Str::uuid(),'acknowledge'=>'1'])->assertSessionHasNoErrors();$link=AppointmentConfirmation::sole();$this->post(route('confirmation.respond',$link->token),['choice'=>'cancelled','acknowledge'=>'1'])->assertRedirect();$this->post(route('confirmation.respond',$link->token),['choice'=>'cancelled','acknowledge'=>'1'])->assertRedirect();$this->assertSame('pending',$f->fresh()->status);$this->assertSame(1,Event::where('event','reopened')->count());$this->assertNull(Event::where('event','reopened')->first()->actor_id);}
 public function test_close_reopen_archive_and_optional_references():void{$f=$this->entry(['professional_id'=>null,'service_id'=>null]);$this->post(route('followups.state',$f->id),['revision'=>$f->revision,'action'=>'close','reason'=>'Paciente desistiu'])->assertSessionHasNoErrors();$this->post(route('appointments.store'),$this->booking($f->fresh()))->assertSessionHasErrors('followup_id');$this->post(route('followups.state',$f->id),['revision'=>$f->fresh()->revision,'action'=>'reopen','reason'=>'Paciente solicitou retorno'])->assertSessionHasNoErrors();$this->patient->update(['active'=>false]);$this->get(route('followups.show',$f->id))->assertOk()->assertDontSee('Agendar atendimento');$this->get(route('followups.edit',$f->id))->assertOk()->assertSee('(arquivado)');$this->get(route('appointments.create',['followup_id'=>$f->id]))->assertSessionHasErrors('followup_id');$this->patient->update(['active'=>true]);$this->book($f->fresh());}
 public function test_tenant_and_role_isolation_and_foreign_catalog():void{$f=$this->entry();$other=Company::create(['name'=>'Outra clínica','slug'=>'other-followups']);$otherPatient=Customer::create(['company_id'=>$other->id,'name'=>'Paciente externo','active'=>true]);$this->post(route('followups.store'),$this->form(['customer_id'=>$otherPatient->id]))->assertNotFound();$this->flushSession();$this->actingAs($this->user('owner',$other));$this->get(route('followups.index'))->assertOk()->assertDontSee('Paciente teste');foreach(['show','edit'] as $route)$this->get(route('followups.'.$route,$f->id))->assertNotFound();$this->get(route('appointments.create',['followup_id'=>$f->id]))->assertNotFound();$this->flushSession();$this->actingAs($this->dentist);foreach(['index','create','show','edit'] as $route)$this->get(route('followups.'.$route,in_array($route,['show','edit'])?$f->id:[]))->assertForbidden();$this->post(route('followups.store'),$this->form())->assertForbidden();$this->get(route('appointments.create',['followup_id'=>$f->id]))->assertForbidden();$this->flushSession();$this->actingAs($this->user('reception'))->get(route('followups.show',$f->id))->assertOk();}
 public function test_filters_include_overdue_and_exclude_future_closed():void{$past=$this->entry(['from_date'=>'2026-09-01','to_date'=>null]);$future=$this->entry(['from_date'=>'2026-12-01','to_date'=>null]);$closed=$this->entry();$this->post(route('followups.state',$closed->id),['revision'=>$closed->revision,'action'=>'close','reason'=>'Paciente desistiu']);$this->get(route('followups.index'))->assertOk()->assertViewHas('entries',fn($rows)=>$rows->count()===1&&$rows->first()->id===$past->id);$this->get(route('followups.index',['state'=>'all','until'=>'2026-12-31']))->assertOk()->assertViewHas('entries',fn($rows)=>$rows->count()===3);$this->get(route('followups.index',['kind'=>'waitlist']))->assertOk()->assertSee('Nenhuma solicitação encontrada')->assertDontSee('<th>Paciente</th>',false);}
}
